'use strict';
function publicCaseKey(c){
 if(c.sourceKey)return c.sourceKey;
 const raw=String(c.url||'');let u;try{u=new URL(raw);}catch{return raw;}
 const blackcat=u.pathname.match(/\/complaint\/view\/(\d+)/);
 if(u.hostname.includes('tousu.sina.')&&blackcat)return 'blackcat:'+blackcat[1];
 const xfb=u.pathname.match(/\/tousu\/(\d+)/);
 if(/xfb(315|365)\.com$/.test(u.hostname)&&xfb)return 'xfb:'+xfb[1];
 let path;try{path=decodeURIComponent(u.pathname);}catch{path=u.pathname;}
 if(u.hostname==='zh.wikisource.org')path=path.replace(/^\/(zh-hans|zh-hant|wiki)\//,'/wiki/');
 return u.hostname.replace(/^m\.bjnews/,'www.bjnews')+path.replace(/\/$/,'');
}
const publicCasePlatform=c=>c.platform||(String(c.type).includes('黑猫')?'黑猫投诉':String(c.type).includes('消费保')?'消费保':String(c.type).includes('App')?'应用商店':String(c.type).includes('自述')||String(c.type).includes('知乎')?'用户帖子':'媒体 / 公开网页');
function publicCases(r){const map=new Map(),byId=new Map();for(const c of [...(r.cases||[]),...(r.complaintAudit?.cases||[]),...(r.governmentAudit?.cases||[])]){const key=byId.get(c.existingCaseId||c.id)||publicCaseKey(c);map.set(key,{...(map.get(key)||{}),...c,brand:r.name,platform:publicCasePlatform(c)});if(c.id)byId.set(c.id,key);}return [...map.values()];}
const reputationSummary=r=>r.complaintAudit?[r.complaintAudit.summary,r.governmentAudit?.hasResults?'官方公示：'+r.governmentAudit.summary:''].filter(Boolean).join(' '):r.reputation;
const relevanceLabel=e=>({'beijing-childcare':'北京育儿相关','other-city-childcare':'异地育儿参考','other-service':'其他服务 / 经营记录','unclear':'城市或工种未充分明确'}[e.relevance]||'范围见材料说明');
const complaintSummary=r=>r.complaintAudit?.summary||'本轮补查记录尚未载入。';
function complaintHighlight(r){if(!r.complaintAudit)return '';return `<div class="complaint-highlight"><strong>本轮投诉补查</strong><p>${esc(complaintSummary(r))}</p>${r.governmentAudit?`<p class="micro">官方公示：${esc(r.governmentAudit.summary)}</p>`:''}<a class="source-link" href="#complaints">查看投诉与处理专页 →</a></div>`;}
function governmentAuditSection(r){const g=r.governmentAudit;if(!g)return '';return `<details class="method gov-audit"><summary>12315 官方公示核查 · ${g.queries.length} 组名称查询</summary><p>${esc(g.summary)}</p><p class="scope-text">${esc(g.limit)}</p>${g.queries.map(q=>`<article class="audit-query"><strong>${esc(q.query)}</strong><p>${esc(q.resultSummary)}</p><a class="source-link" href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">打开官方公示平台，按此名称查询 ↗</a></article>`).join('')}</details>`;}
function complaintAuditSection(r){const a=r.complaintAudit;if(!a)return '';return `<section class="detail-section complaint-detail"><h3>投诉平台与监管媒体补查</h3><p>${esc(a.summary)}</p><p class="scope-text">${esc(a.coverageLimit)}</p>${governmentAuditSection(r)}<details class="method"><summary>本轮实际检索记录 · ${a.queries.length} 组</summary><p class="scope-text">下列链接是搜索返回的候选，可能含无关或未能回读的页面；是否采信、读取情况与归属边界见具体材料。</p><div class="query-log">${a.queries.map(q=>`<article><strong>${esc(q.query)}</strong><span>${esc(q.channel)} · ${esc(q.method)}${q.status==='failed'?' · 未完成查询':''}</span><p>${esc(q.resultSummary)}</p>${(q.resultUrls||[]).map(u=>`<a class="source-link" href="${esc(u)}" target="_blank" rel="noopener noreferrer">查看检索候选 ↗</a>`).join('')}</article>`).join('')}</div></details>${a.excluded?.length?`<details class="method"><summary>本轮排除的同名或不相关材料 · ${a.excluded.length} 条</summary>${a.excluded.map(x=>`<p>${esc(x.reason)}${x.url?` <a class="source-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">查看原材料 ↗</a>`:''}</p>`).join('')}</details>`:''}</section>`;}
function complaintStatus(r){const a=r.complaintAudit;return a?.cases?.length||r.governmentAudit?.cases?.length?'material':r.governmentAudit?.hasResults?'official':'limited';}
function setupComplaints(){const m=DATA.complaintReview;if(!m)return;$('#complaints').innerHTML=head('COMPLAINTS & FOLLOW-UP','不止看评价，也看投诉怎么处理','逐家核查投诉平台、官方公示及监管媒体材料。把发生了什么、谁作出回应、最后处理到哪一步放在一起看。')+`<div class="score-overview"><div><b>${m.agencies}</b><span>条目均完成多渠道补查</span></div><div><b>${m.webQueries}</b><span>逐家公开网页查询</span></div><div><b>${m.govQueries}</b><span>12315 站内名称查询</span></div></div><div class="evidence-note"><strong>有公示、有投诉，不等于已经认定违法；没有检索结果，也不等于没有纠纷。</strong><p>官方公示含当事人填报内容及调解结果；投诉平台以用户陈述为主。“系统自动完成”“达成调解协议”“消费者确认退款”分别记录。异地、其他工种、培训和劳动争议不会当成北京育儿嫂订单。资料数量不用于计算投诉率或扣分。</p><p>12315 公示期限为一年。本轮按现有法人线索或品牌查询并查看结果首屏，对选取的具名记录回读详情；没有遍历所有历史记录及全部分支。58同城、京东商城的多商户频道按商户核查，不按整个频道合并。</p></div><details class="method"><summary>查询渠道与实际覆盖范围</summary><div class="channel-grid">${m.channels.map(c=>`<article><h3>${esc(c.name)}</h3><p>${esc(c.method)}</p><p class="scope-text">${esc(c.limit)}</p>${c.url?`<a class="source-link" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">平台或官方说明 ↗</a>`:''}</article>`).join('')}</div></details><div class="section-heading"><h2>逐家补查结果</h2><a class="source-link" href="complaints.csv" download>下载投诉核查表 ↓</a></div><div class="filters complaint-filters"><label class="search-label"><span>查找机构或主体</span><input type="search" id="complaint-search" placeholder="例如：阿姨来了、国选、万婴宝"></label><label><span>本轮材料情况</span><select id="complaint-status"><option value="all">全部 125 个条目</option><option value="material">有可展开的材料</option><option value="official">仅有官方列表线索</option><option value="limited">本轮未取得可归属个案</option></select></label></div><div class="results-line"><p role="status" aria-live="polite" id="complaint-count"></p><button class="text-button" id="complaint-reset">重置投诉筛选</button></div><div id="complaint-results"></div><details class="method"><summary>官方规则与行业背景 · 不归因于任何一家机构</summary>${m.background.map(b=>`<article class="audit-query"><h3>${esc(b.title)}</h3><p>${esc(b.summary)}</p><p class="scope-text">${esc(b.limit)}</p><a class="source-link" href="${esc(b.url)}" target="_blank" rel="noopener noreferrer">原始来源 ↗</a></article>`).join('')}</details>`;['complaint-search','complaint-status'].forEach(id=>$('#'+id).addEventListener('input',renderComplaints));$('#complaint-reset').addEventListener('click',()=>{$('#complaint-search').value='';$('#complaint-status').value='all';renderComplaints();});renderComplaints();}
function renderComplaints(){const q=$('#complaint-search').value.trim().toLowerCase(),s=$('#complaint-status').value;const rows=items.filter(r=>(!q||[r.name,...(r.governmentAudit?.queries||[]).map(x=>x.query)].join(' ').toLowerCase().includes(q))&&(s==='all'||complaintStatus(r)===s));$('#complaint-count').textContent=`显示 ${rows.length} / ${items.length} 个已补查条目 · 顺序沿用调查目录，不按投诉数量排名`;$('#complaint-results').innerHTML=rows.length?rows.map(r=>{const a=r.complaintAudit,g=r.governmentAudit;const latest=publicCases(r).filter(c=>c.complaintUpdate||c.platform==='12315官方公示');return `<article class="complaint-agency"><div class="complaint-agency-heading"><div><h3><button class="name-button" data-agency="${esc(r.id)}">${esc(name(r.name))}</button></h3><span class="table-sub">${esc(businessLabel(r))} · ${a.queries.length} 组网页查询${g?.queries.length?` · ${g.queries.length} 组官方查询`:''}</span></div><span class="tag ${latest.length?'amber':''}">${latest.length?'有材料，需结合边界核实':g?.hasResults?'官方列表有线索':'未取得可归属个案'}</span></div><p class="complaint-conclusion">${esc(a.summary)}</p>${g?`<p class="gov-summary"><strong>官方公示核查：</strong>${esc(g.summary)}</p>`:''}${latest.length?`<details class="complaint-materials"><summary>展开本轮材料与处理结果 · ${latest.length} 条</summary>${latest.map(caseCard).join('')}</details>`:''}<div class="complaint-agency-bottom">${openButton(r,'看完整档案、检索记录与来源')}<span class="micro">未命中不是零投诉证明</span></div></article>`;}).join(''):'<div class="empty">没有符合条件的条目，试试缩短关键词或重置筛选。</div>';}
